apiVersion: external-secrets.io/v1beta1
kind: ExternalSecret
metadata: { name: db-pass }
spec:
  refreshInterval: 1h                 # 每小时同步一次
  secretStoreRef: { name: vault-backend, kind: ClusterSecretStore }
  target: { name: db-pass }           # 生成的集群内 Secret 名
  data:
  - secretKey: password
    remoteRef: { key: prod/db, property: password }

# templates/deployment.yaml 片段
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "mychart.fullname" . }}     # . 是根作用域
spec:
  {{- if .Values.autoscaling.enabled }}        # 条件控制
  replicas: {{ .Values.autoscaling.minReplicas }}
  {{- else }}
  replicas: {{ .Values.replicaCount }}
  {{- end }}
  # 配置变更触发滚动更新的通用技巧：
  template:
    metadata:
      annotations:
        checksum/config: {{ include (print $.Template.BasePath "/configmap.yaml") . | sha256sum }}
